using System.Numerics;

namespace DotCharter.Services.Parsing.Eof;

/// <summary>Exporter-capable kinds and records generated by the real target writer cannot veto a grace.</summary>
internal sealed class EofGraceAttachments
{
    private enum Kind
    {
        BendTech,
        SlideTech,
        OtherTech,
        Trill,
        Tremolo,
        Shape,
        Anchor,
        Tone,
        GhostGrip,
        Fingering,
        Text
    }

    // Simple generated kinds need no further proof. An override needs the real
    // exporter's emission, rather than a second description of its wire shape.
    private static readonly Dictionary<Kind, bool> GeneratedCapable = new()
    {
        [Kind.BendTech] = true,
        [Kind.SlideTech] = false,
        [Kind.OtherTech] = false,
        [Kind.Trill] = false,
        [Kind.Tremolo] = true,
        [Kind.Shape] = true,
        [Kind.Anchor] = true,
        [Kind.Tone] = true,
        [Kind.GhostGrip] = true,
        [Kind.Fingering] = true,
        [Kind.Text] = true
    };

    private readonly IReadOnlyList<EofRawProGuitarNote> _techNotes;
    private readonly IReadOnlyList<EofRawProGuitarNote> _allTechNotes;
    private Dictionary<(byte Difficulty, uint Position), List<EofRawProGuitarNote>> _owners = [];
    private readonly IReadOnlyList<(int diff, uint startMs, uint endMs)> _trills;

    private EofGraceAttachments(IReadOnlyList<EofRawProGuitarNote> techNotes,
        IReadOnlyList<(int diff, uint startMs, uint endMs)> trills)
    {
        _allTechNotes = techNotes.OrderBy(t => t.PositionMs).ToArray();
        _techNotes = _allTechNotes.Where(t => !GeneratedCapable[TechKind(t)]).ToArray();
        _trills = trills;
    }

    public static EofGraceAttachments Create(IReadOnlyList<EofRawProGuitarNote> techNotes,
        IEnumerable<(int diff, uint startMs, uint endMs)> trills) =>
        new(techNotes,
            trills.Where(_ => !GeneratedCapable[Kind.Trill]).ToArray());

    // Mixed slide/bend edits require proof too: no writer emits such a combined record.
    private static Kind TechKind(EofRawProGuitarNote tech)
    {
        const uint slides = EofConstants.PgFlagSlideUp | EofConstants.PgFlagSlideDown | EofConstants.PgFlagUnpitchedSlide;
        if ((tech.Flags & slides) != 0) return Kind.SlideTech;
        return (tech.Flags & EofConstants.PgFlagBend) != 0 ? Kind.BendTech : Kind.OtherTech;
    }

    public void PrepareOwners(IReadOnlyList<EofRawProGuitarNote> notes, Dictionary<int, int> pairs)
    {
        if (_techNotes.Count == 0) return;
        _owners = EofGraceTargetTech.Owners(notes, pairs).GroupBy(n => (n.Difficulty, n.PositionMs))
            .ToDictionary(g => g.Key, g => g.ToList());
    }

    public bool Touches(EofRawProGuitarNote ornament, EofRawProGuitarNote target, int capo, IList<BeatMarker> beats)
    {
        var s = BitOperations.TrailingZeroCount((uint)ornament.NoteBitmask);
        var generated = new Dictionary<EofRawProGuitarNote, IReadOnlyList<EofRawProGuitarNote>>();
        for (var i = EofProGuitarTrackParser.FirstTechNoteAtOrAfter(_techNotes, ornament.PositionMs); i < _techNotes.Count; i++)
        {
            var tech = _techNotes[i];
            if (tech.PositionMs > target.PositionMs) break;
            // The canonical ornament ends exactly at the target attack; its
            // application range includes that attack without the target sustain.
            if (!EofAttachmentApplicability.TechNoteApplies(tech, ornament, s)) continue;
            if (!IsGenerated(tech, generated, capo, beats)) return true;
        }
        return _trills.Any(section => EofAttachmentApplicability.SectionApplies(section, ornament) ||
                                      EofAttachmentApplicability.SectionApplies(section, target));
    }

    private bool IsGenerated(EofRawProGuitarNote tech,
        Dictionary<EofRawProGuitarNote, IReadOnlyList<EofRawProGuitarNote>> generated, int capo, IList<BeatMarker> beats)
    {
        if (!_owners.TryGetValue((tech.Difficulty, tech.PositionMs), out var owners)) return false;
        foreach (var owner in owners)
        {
            if (!generated.TryGetValue(owner, out var records))
            {
                records = EofGraceTargetTech.Build(owner, _allTechNotes, capo, beats);
                generated[owner] = records;
            }
            if (records.Any(expected => EofGraceTargetTech.SameRecord(expected, tech))) return true;
        }
        return false;
    }
}
